self.addEventListener('push',event=>{let data;try{data=event.data.json()}catch{data={title:'出门前',body:'天气更新失败，请稍后查看今天的出门建议。'}}event.waitUntil(self.registration.showNotification(data.title||'出门前',{body:data.body,tag:'chumen-daily',icon:'favicon.svg',data:{url:'./'}}))});
self.addEventListener('notificationclick',event=>{event.notification.close();event.waitUntil((async()=>{const windows=await self.clients.matchAll({type:'window',includeUncontrolled:true});for(const win of windows){if(new URL(win.url).origin===self.location.origin){await win.focus();await win.navigate(new URL('./',self.location).href);return}}await self.clients.openWindow('./')})())});
